from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    pairs = []
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    pairs.append((r, c, dc, color))
    for r, c, dc, color in pairs:
        # Extend away from both ends of each diagonal pair, stopping at a blocker.
        for rr, cc, dr, stepc in ((r - 1, c - dc, -1, -dc), (r + 2, c + 2 * dc, 1, dc)):
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == bg:
                    out[rr][cc] = color
                elif grid[rr][cc] != color:
                    break
                rr += dr
                cc += stepc
    return out
